// ── Conversation State Machine ───────────────────────────────
// Tracks each Telegram chat's progress through the 6 questions,
// then asks for a YES/NO confirmation before firing the CRM call.
// State persists via workflow static data (only when the workflow
// is ACTIVE — test executions don't persist state).

const staticData = $getWorkflowStaticData('global');
const msg = $input.first().json.message ?? {};
const chatId = String(msg.chat?.id ?? '');
const text = (msg.text || '').trim();
const lower = text.toLowerCase();

const QUESTIONS = [
  { key: 'targeting',  prompt: '🎯 1/6 — Who are you targeting?\n(industry, job title, company size, location)' },
  { key: 'goal',       prompt: '🥅 2/6 — What is your goal with these prospects?\n(cold outreach, demos, partnerships, etc.)' },
  { key: 'tone',       prompt: '🗣️ 3/6 — What tone or message style?\n(formal, casual, direct)' },
  { key: 'volume',     prompt: '🔢 4/6 — How many prospects do you want?' },
  { key: 'exclusions', prompt: '🚫 5/6 — Any exclusions?\n(existing clients, competitors, regions to avoid — or say "none")' },
  { key: 'channel',    prompt: '📡 6/6 — What channel will you reach out on?\n(email, SMS, LinkedIn, etc.)' }
];

if (!staticData.sessions) staticData.sessions = {};

const reply = (action, replyText, payload = null) =>
  [{ json: { chatId, action, replyText, payload } }];

// ── Start / restart ──
if (!staticData.sessions[chatId] || lower === '/start' || lower === '/restart' || lower === 'restart') {
  staticData.sessions[chatId] = { step: 0, answers: {} };
  return reply('ask',
    `👋 Let's find you some prospects! I'll ask 6 quick questions.\n` +
    `(Type /restart at any time to start over.)\n\n${QUESTIONS[0].prompt}`);
}

const session = staticData.sessions[chatId];

// ── Awaiting YES/NO confirmation ──
if (session.step === 'confirm') {
  if (['yes', 'y', '✅', 'confirm'].includes(lower)) {
    const payload = {
      chat_id: chatId,
      requested_at: new Date().toISOString(),
      ...session.answers
    };
    delete staticData.sessions[chatId];
    return reply('fire',
      `🚀 Launching the AI Prospecting workflow now — I'll message you here when the results are in!`,
      payload);
  }
  if (['no', 'n', '❌'].includes(lower)) {
    session.step = 0;
    session.answers = {};
    return reply('ask', `No problem — let's run through it again.\n\n${QUESTIONS[0].prompt}`);
  }
  return reply('ask', `Please reply YES to launch or NO to start over. 🙂`);
}

// ── Collecting answers (vague-answer guard) ──
if (text.length < 2) {
  return reply('ask', `Could you give me a bit more detail? 🙏\n\n${QUESTIONS[session.step].prompt}`);
}

session.answers[QUESTIONS[session.step].key] = text;
session.step += 1;

if (session.step < QUESTIONS.length) {
  return reply('ask', QUESTIONS[session.step].prompt);
}

// ── All 6 answered → confirmation summary ──
session.step = 'confirm';
const a = session.answers;
const summary =
  `📋 Here's what I have:\n\n` +
  `🎯 Targeting: ${a.targeting}\n` +
  `🥅 Goal: ${a.goal}\n` +
  `🗣️ Tone: ${a.tone}\n` +
  `🔢 Volume: ${a.volume}\n` +
  `🚫 Exclusions: ${a.exclusions}\n` +
  `📡 Channel: ${a.channel}\n\n` +
  `Does this look right? Reply YES to launch or NO to start over.`;
return reply('ask', summary);

// ── Format CRM results for Telegram ──────────────────────────
// Expects the CRM to POST back:
// { "chat_id": "...", "count": 12, "prospects": [{ "name": "", "company": "", "title": "" }] }

const body = $input.first().json.body ?? $input.first().json;
const chatId = String(body.chat_id ?? '');
const prospects = Array.isArray(body.prospects) ? body.prospects : [];
const count = body.count ?? prospects.length;

let text;
if (count === 0) {
  text = `⚠️ Prospecting finished but returned 0 prospects.\nTry broadening your criteria — send /start to run it again.`;
} else {
  text = `✅ Prospecting complete! Found ${count} prospects and added them to your CRM contacts:\n\n`;
  for (const p of prospects.slice(0, 20)) {
    const parts = [p.name ?? 'Unknown', p.title, p.company ? `@ ${p.company}` : null].filter(Boolean);
    text += `• ${parts.join(' — ')}\n`;
  }
  if (prospects.length > 20) {
    text += `\n…and ${prospects.length - 20} more (see your CRM contacts).`;
  }
  text += `\n\nSend /start to run another search. 🚀`;
}

return [{ json: { chatId, text } }];
